    _re_ru_asmr_prompt = r"(root|serviceuser|rfsw)@.*Node\d+:.*# "  # root@5GW5-Node0:~#
    _re_ru_hub_prompt = r"toor4nsn@fzhub\d+\d+:.*# "  # toor4nsn@fzhub10:~#
    _re_ru_moler_prompt = r"\S+@molerRU.*>"
    _re_ru_prompt = f"(({_re_ru_moler_prompt})|({_re_ru_legacy_prompt})|({_re_ru_new_prompt})|({_re_ru_asmr_prompt})|({_re_ru_hub_prompt}))"
