    _re_frmonshell_prompt = r"^\$\s*$"
    _re_rfsw_cli_prompt = r"^rfsw>\s*$"

    def __init__(
            self,
            sm_params,
            name=None,
            io_connection=None,
            io_type=None,
            variant=None,
            io_constructor_kwargs=None,
            initial_state=None,
            lazy_cmds_events=False,
            serial_number=None,
    ):
        """
        Create Unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        :param serial_number: serial number of device
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else RadioUnit3.bts

        self._use_bts = self._is_bts_in_sm_params(sm_params=sm_params)
        self._login_via_master = self._is_master_in_sm_params(sm_params=sm_params)
        super(RadioUnit3, self).__init__(
            sm_params=sm_params,
            name=name,
            io_connection=io_connection,
            io_type=io_type,
            variant=variant,
            io_constructor_kwargs=io_constructor_kwargs,
            initial_state=initial_state,
            lazy_cmds_events=lazy_cmds_events,
        )
        self.logger = logging.getLogger("moler.ru")
        self._last_success_ru_from = RadioUnit3.fhnet  # or RadioUnit.bts
        self._serial_number = serial_number

    @property
    def ru_ip_address(self):
        """
        Get ru_ip address.

        :return: ru_ip_address
        """
        ip_address = None
        ru_state = self.__get_ru_state()
        if ru_state:
            ip_address = ru_state["command_params"]["host"]
        else:
            self.logger.warning("RU state not defined")
        return ip_address

    @ru_ip_address.setter
    def ru_ip_address(self, ip_address):
        """
        Change ru ip address.

        :param ip_address:    IP address to RU
        :return: None
        """
        ru_state = self.__get_ru_state()
        if ru_state:
            ru_state["command_params"]["host"] = ip_address
        else:
            self.logger.warning("RU state not defined")

    @property
    def ru_password(self):
        """
        Get current ru_password.

        :return: ru_password
        """
        ru_state = self.__get_ru_state()
        password = ru_state["command_params"]["password"]
        return password

    @ru_password.setter
    def ru_password(self, password):
        """
        Change ru_password.

        :param password:    RU password
        :return: None
        """
        ru_state = self.__get_ru_state()
        ru_state["command_params"]["password"] = password

    @property
    def container_id(self):
        """
        Get container id of state FHNET. If RU is connected directly (no state FHNET) then return None.

        :return: container id
        """
        container = None
        try:
            container = self._configurations[RadioUnit3.connection_hops][RadioUnit3.bts][RadioUnit3.fhnet]["command_params"]["name"]
        except KeyError:
            pass
        return container

    @container_id.setter
    def container_id(self, container_id):
        """
        Change container id for state FHNET. If RU is connected directly (no state FHNET) then no efect.

        :param container_id: Id of container to go to the state FHNET.
        :return: None.
        """
        try:
            self._configurations[RadioUnit3.connection_hops][RadioUnit3.bts][RadioUnit3.fhnet]["command_params"]["name"] = container_id
        except KeyError:
            pass

    @property
    def serial_number(self):
        """
        Get RU serial number.

        :return: RU serial number.
        """
        return self._serial_number

    @serial_number.setter
    def serial_number(self, serial_number):
        """
        Change ru serial number.

        :param serial_number:    RU serial number
        :return: None
        """
        self._serial_number = serial_number

    def __get_ru_state(self):
        possible_states = [[RadioUnit3.fhnet, RadioUnit3.ru], [RadioUnit3.proxy_pc, RadioUnit3.ru], [RadioUnit3.unix_local, RadioUnit3.ru]]
        ru_state = None
        for states in possible_states:
            try:
                ru_state = self._configurations[RadioUnit3.connection_hops][states[0]][states[1]]
                return ru_state
            except KeyError:
                pass

        return ru_state

    def _get_default_sm_configuration(self):
        """
        Create State Machine default configuration for RU.

        :return: default sm configuration.
        """
        config = super(RadioUnit3, self)._get_default_sm_configuration()
        if self._use_proxy_pc:
            if self._login_via_master:
                default_config = self._get_default_sm_configuration_with_proxy_pc_with_master_and_bts()
            elif self._use_bts:
                default_config = self._get_default_sm_configuration_with_proxy_pc_with_bts()
            else:
                default_config = self._get_default_sm_configuration_with_proxy_pc_without_bts()
        else:
            if self._login_via_master:
                default_config = self._get_default_sm_configuration_without_proxy_pc_with_master_and_bts()
            elif self._use_bts:
                default_config = self._get_default_sm_configuration_without_proxy_pc_with_bts()
            else:
                default_config = self._get_default_sm_configuration_without_proxy_pc_without_bts()
        self._update_dict(config, default_config)
        return config

    def _is_bts_in_sm_params(self, sm_params):
        """
        Check that bts state is inside sm configuration.

        :param sm_params: sm configuration
        :return: True when bts state exist, otherwise False
        """
        return self._is_proxy_pc_in_sm_params(sm_params=sm_params, proxy=RadioUnit3.bts)

    def _is_master_in_sm_params(self, sm_params):
        """
        Check that bts state is inside sm configuration.

        :param sm_params: sm configuration
        :return: True when bts state exist, otherwise False
        """
        return self._is_proxy_pc_in_sm_params(sm_params=sm_params, proxy=RadioUnit3.master)

