    def _prepare_transitions(self):
        """
        Prepare transitions to change states.

        :return: None.
        """
        super(RadioUnit3, self)._prepare_transitions()
        if self._use_proxy_pc:
            if self._login_via_master:
                transitions = self._prepare_transitions_with_proxy_pc_with_master_and_bts()
            elif self._use_bts:
                transitions = self._prepare_transitions_with_proxy_pc_with_bts()
            else:
                transitions = self._prepare_transitions_with_proxy_pc_without_bts()
        else:
            if self._login_via_master:
                transitions = self._prepare_transitions_without_proxy_pc_with_master_and_bts()
            elif self._use_bts:
                transitions = self._prepare_transitions_without_proxy_pc_with_bts()
            else:
                transitions = self._prepare_transitions_without_proxy_pc_without_bts()
        self._add_transitions(transitions=transitions)

