    def _prepare_state_hops(self):
        """
        Prepare hops for non direct transitions between states.

        :return: None.
        """
        super(RadioUnit3, self)._prepare_state_hops()

        if self._use_proxy_pc:
            if self._login_via_master:
                state_hops = self._prepare_state_hops_with_proxy_pc_with_master_and_bts()
            elif self._use_bts:
                state_hops = self._prepare_state_hops_with_proxy_pc_with_bts()
            else:
                state_hops = self._prepare_state_hops_with_proxy_pc_without_bts()
        else:
            if self._login_via_master:
                state_hops = self._prepare_state_hops_without_proxy_pc_with_master_and_bts()
            elif self._use_bts:
                state_hops = self._prepare_state_hops_without_proxy_pc_with_bts()
            else:
                state_hops = self._prepare_state_hops_without_proxy_pc_without_bts()

        self._update_dict(self._state_hops, state_hops)

