    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(RadioUnit3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == RadioUnit3.bts or state == RadioUnit3.master:
                available = {
                    RadioUnit3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.shared.enblinux", "ta_moler.cmd.airscale.fct"],
                    RadioUnit3.events: ["moler.events.shared", "moler.events.unix"],
                }
            elif state == RadioUnit3.ru:
                available = {
                    RadioUnit3.cmds: [
                        "moler.cmd.unix",
                        "ta_moler.cmd.shared.nokiaunix",
                        "ta_moler.cmd.ru",
                        "ta_moler.cmd.hub.linux",
                        "ta_moler.cmd.hub.linux",
                        "ta_moler.cmd.ru.linux",
                    ],
                    RadioUnit3.events: ["moler.events.shared", "moler.events.unix"],
                }
            elif state == RadioUnit3.fhnet:
                available = {
                    RadioUnit3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.shared.enblinux"],
                    RadioUnit3.events: ["moler.events.shared", "moler.events.unix"],
                }
            elif state == RadioUnit3.frmonshell:
                available = {
                    RadioUnit3.cmds: ["ta_moler.cmd.ru.frmonshell",],
                    RadioUnit3.events: ["moler.events.shared", "moler.events.unix"],
                }
            elif state == RadioUnit3.rfsw_cli:
                available = {
                    RadioUnit3.cmds: ["ta_moler.cmd.hub.rfswcli"],
                    RadioUnit3.events: ["moler.events.shared", "moler.events.unix"],
                }
            if available:
                return available[observer]

        return available

    def _execute_goto_to_fhnet_or_ru(self, source_state, dest_state, timeout=-1):
        """
        Execute action to change state to FHNET or RU (if FHNET fails).

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout.
        :return: None.
        """
        if self._last_success_ru_from == RadioUnit3.fhnet:
            try:
                self._log(logging.INFO, "Try lxc to FHNET.")
                self._execute_command_bts_fhnet(source_state=source_state, dest_state=dest_state, timeout=timeout)
                self._last_success_ru_from = RadioUnit3.fhnet
            except MolerException:
                self._log(logging.INFO, "Cannot go to FHNET, try to go to RU directly form BTS.")
                self._execute_bts_to_ru(source_state=source_state, dest_state=dest_state, timeout=timeout)
                self._last_success_ru_from = RadioUnit3.bts
        else:
            try:
                self._log(logging.INFO, "Try to go to RU directly form BTS.")
                self._execute_bts_to_ru(source_state=source_state, dest_state=dest_state, timeout=timeout)
                self._last_success_ru_from = RadioUnit3.bts
            except MolerException:
                self._log(logging.INFO, "Cannot goto to RU, Try lxc to FHNET.")
                self._execute_command_bts_fhnet(source_state=source_state, dest_state=dest_state, timeout=timeout)
                self._last_success_ru_from = RadioUnit3.fhnet

    # pylint: disable-next=unused-argument
    def _execute_bts_to_ru(self, source_state, dest_state, timeout=-1, retried=False):
        """
        Execute action to change state from state BTS to state RU.

        :param timeout: transition timeout.
        :return: None.
        """
        configurations = self._configurations[RadioUnit3.connection_hops][RadioUnit3.fhnet][RadioUnit3.ru]
        command_name = configurations["execute_command"]
        command_params = configurations["command_params"]
        if not command_params["host"]:
            command_params["host"] = self.detect_ru_host()
        command_timeout = self.calc_timeout_for_command(timeout, command_params)
        command_params_without_timeout = self._parameters_without_timeout(parameters=command_params)
        command = self.get_cmd(cmd_name=command_name, cmd_params=command_params_without_timeout)
        try:
            command(timeout=command_timeout)
            command_params["password"] = command._last_password
        except MolerException as ex:
            if "Could not resolve hostname" in str(ex) and retried is False:
                self.ru_ip_address = self.detect_ru_host()
                self._execute_bts_to_ru(source_state=source_state, dest_state=dest_state, timeout=timeout, retried=True)
            else:
                raise ex

    def _execute_command_bts_fhnet(self, source_state, dest_state, timeout=-1):
        """
        Execute command to change state from fct to lxc.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout.
        :return: None.
        :raise DeviceChangeStateFailure if cannot detect container id
        """
        lxc_state = self._configurations[RadioUnit3.connection_hops][RadioUnit3.bts][RadioUnit3.fhnet]
        container_id = lxc_state["command_params"]["name"]
        if container_id is None:
            container_id = self.detect_fhnet_container_id()
            if container_id is None:
                raise DeviceChangeStateFailure(device=self.name, exception="Cannot get dynamically container id.")
        self._execute_command_to_change_state(source_state=source_state, dest_state=dest_state, timeout=timeout)

    def change_fhnet_container_id(self, container_id):
        """
        Change container ID.

        :param container_id:    ASICNTR container ID eg:  0xe019
        :return: None
        """
        lxc_state = self._configurations[RadioUnit3.connection_hops][RadioUnit3.bts][RadioUnit3.fhnet]
        lxc_state["command_params"]["name"] = container_id

    _container_fhnet_id_ps = re.compile(r"/ram/node_FHNET[08]0/lxc.cfg -n (?P<CONTAINER_ID>\S+)")

    def detect_fhnet_container_id(self, max_try=5):
        """
        Change container id dynamically.

        :return: id of container
        """
        attempt = 0
        container_id = None
        while attempt <= max_try and container_id is None:
            attempt += 1
            try:
                ps_cmd = self.get_cmd(cmd_name="ps", cmd_params={"options": "-ef"})
                result = ps_cmd()
                for process in result:
                    m = re.search(RadioUnit3._container_fhnet_id_ps, process["CMD"])
                    if m:
                        container_id = m.group("CONTAINER_ID")
                        break
            except MolerException:
                continue
        if container_id:
            self.change_fhnet_container_id(container_id)
        return container_id

    def detect_ru_host(self, max_try=5, state="FHNET", path=r"/rom/config/FRIps.txt", serial_number=None):
        """
        Detect hub/RU host dynamically.

        :param max_try: how many times try to detect address
        :param state: name of state to execute commands, None if method does not change state
        :param path: path to file to parse the IP address
        :param serial_number: serial number of Radio Unit. If None, use serial number of Radio Unit.
        :return: address of RU/HUB
        """
        serial_number = serial_number if serial_number is not None else self.serial_number
        if serial_number is None:
            raise DeviceFailure(self.name, "Serial number is not set, cannot get proper IP address for RU")
        attempt = 0
        ru_address = None
        host_regex = re.compile(r"\b(?P<HOST>(?:\d{1,3}\.){3}\d{1,3})\b")
        while attempt <= max_try and ru_address is None:
            if state is not None:
                self.goto_state(state=state, rerun=max_try)
            attempt += 1
            try:
                cat_cmd = self.get_cmd(cmd_name="cat", cmd_params={"path": path})
                result = cat_cmd()
                for line in result["LINES"]:
                    m = re.search(host_regex, line)
                    if m:
                        if serial_number in line:
                            ru_address = m.group("HOST")
                            self.ru_ip_address = ru_address
                            break
            except MolerException:
                continue
        return ru_address

    @mark_to_call_base_class_method_with_same_name
    def _prepare_newline_chars_with_proxy_pc(self):
        """
        Prepare newline char for each state for State Machine with proxy_pc state.

        :return: newline char for each state with proxy_pc state.
        """
        newline_chars = {
            RadioUnit3.frmonshell:
                "\r\n",
        }
        return newline_chars

    @mark_to_call_base_class_method_with_same_name
    def _prepare_newline_chars_without_proxy_pc(self):
        """
        Prepare newline char for each state for State Machine without proxy_pc state.

        :return: newline char for each state without proxy_pc state.
        """
        newline_chars = {
            RadioUnit3.frmonshell:
                "\r\n",
        }
        return newline_chars
